"""Preview-subject candidate only; never grants movement or combat authority."""

from __future__ import annotations

from collections.abc import Iterable, Mapping


def _positive_int(value: object) -> bool:
    return type(value) is int and value > 0


def choose_quiet_movement_preview_subject_v1(
    snapshot: Mapping[str, object],
    *,
    existing_army_id: int,
    stationary_threat_army_ids: Iterable[int] = (),
    unsafe_route_army_ids: Iterable[int] = (),
) -> dict[str, object]:
    """Rank a quiet preview subject using Driver's exact-frame Army cache.

    The caller still previews this army's route, verifies contact/battle guards,
    and audits every other controlled army. An unreadable CArmy is unknown, not
    zero strength or disposable. This helper never returns an action step.
    """
    denied = {"status": "unavailable", "selected_army_id": None,
              "native_preview_required": True, "movement_authorized": False,
              "battle_authorized": False, "other_army_risk_cleared": False}
    if tuple(stationary_threat_army_ids) or tuple(unsafe_route_army_ids):
        return {**denied, "reason": "not_quiet"}
    actor = snapshot.get("played_character")
    diagnostics = snapshot.get("diagnostics")
    if not (
        snapshot.get("paused") is True
        and snapshot.get("map_ready") is True
        and isinstance(snapshot.get("snapshot_id"), str)
        and snapshot["snapshot_id"]
        and _positive_int(snapshot.get("revision"))
        and _positive_int(snapshot.get("native_revision"))
        and _positive_int(snapshot.get("date_raw"))
        and isinstance(snapshot.get("episode_run_id"), str)
        and snapshot["episode_run_id"]
        and isinstance(actor, Mapping)
        and _positive_int(actor.get("character_id"))
        and isinstance(diagnostics, Mapping)
        and _positive_int(diagnostics.get("connection_generation"))
        and _positive_int(diagnostics.get("bridge_pid"))
        and snapshot.get("army_strengths_profile") == "ordinary_core_v1"
        and snapshot.get("army_strengths_status") in {"available", "partial"}
        and _positive_int(snapshot.get("army_strengths_query_sequence"))
        and snapshot.get("army_strengths_queried_snapshot_id")
            == snapshot["snapshot_id"]
        and snapshot.get("army_strengths_queried_revision")
            == snapshot["revision"]
    ):
        return {**denied, "reason": "exact_army_query_frame_unavailable"}
    armies = snapshot.get("player_armies")
    strength_rows = snapshot.get("army_strengths")
    wars = snapshot.get("active_wars")
    if not isinstance(armies, list) or not isinstance(strength_rows, list) or not isinstance(wars, list):
        return {**denied, "reason": "army_or_war_roster_unavailable"}
    war_army_ids = {
        army.get("army_id")
        for war in wars if isinstance(war, Mapping) and _positive_int(war.get("war_id"))
        for army in (war.get("allied_armies") if isinstance(war.get("allied_armies"), list) else [])
        if isinstance(army, Mapping)
    }
    controlled = [
        army for army in armies if isinstance(army, Mapping)
        and _positive_int(army.get("army_id"))
        and army.get("controllable") is True
        and army.get("owner_character_id") == actor["character_id"]
        and army.get("army_id") in war_army_ids
    ]
    if not controlled or existing_army_id not in {army["army_id"] for army in controlled}:
        return {**denied, "reason": "existing_subject_or_war_roster_unavailable"}
    if any(
        army.get("army_state") in {"combat", "retreating", "gathering"}
        or army.get("in_combat") is True
        or army.get("retreating") is True
        or army.get("move_target_province_id") is not None
        or army.get("route_province_ids") != []
        for army in controlled
    ):
        return {**denied, "reason": "controlled_army_not_quiet"}
    if len({army["army_id"] for army in controlled}) != len(controlled):
        return {**denied, "reason": "duplicate_public_army"}
    indexed: dict[int, Mapping[str, object]] = {}
    for row in strength_rows:
        if not isinstance(row, Mapping) or not _positive_int(row.get("army_id")):
            continue
        army_id = row["army_id"]
        if army_id in indexed:
            return {**denied, "reason": "duplicate_strength_row"}
        indexed[army_id] = row
    if any(army["army_id"] not in indexed for army in controlled):
        return {**denied, "reason": "incomplete_strength_roster"}
    available: list[tuple[int, int]] = []
    unknown: list[int] = []
    for army in controlled:
        army_id = army["army_id"]
        row = indexed[army_id]
        if row.get("scope_role") not in (None, "player"):
            return {**denied, "reason": "strength_scope_not_player"}
        if (row.get("status") == "available"
                and _positive_int(row.get("native_carmy_id"))
                and _positive_int(row.get("current_soldiers"))):
            available.append((row["current_soldiers"], army_id))
        else:
            unknown.append(army_id)
    if not available:
        return {**denied, "reason": "no_native_movement_subject_observed",
                "unknown_army_ids": sorted(unknown)}
    strength, army_id = min(available, key=lambda pair: (-pair[0], pair[1]))
    return {
        "status": "preview_subject_candidate",
        "selected_army_id": army_id,
        "observed_current_soldiers": strength,
        "unknown_army_ids": sorted(unknown),
        "source_query_sequence": snapshot["army_strengths_query_sequence"],
        "source_snapshot_id": snapshot["snapshot_id"],
        "source_revision": snapshot["revision"],
        "native_preview_required": True,
        "movement_authorized": False,
        "battle_authorized": False,
        "other_army_risk_cleared": False,
    }


def choose_threatened_ghost_preview_subject_v1(
    snapshot: Mapping[str, object], *, ghost_army_id: int,
    threatened_army_ids: Iterable[int],
) -> dict[str, object]:
    """Change only the read-only preview subject, retaining ghost threats.

    This bounded case is two stationary controlled CUnits, one
    independently observed without CArmy and one with an actual CArmy. It
    makes no claim that the ghost has zero men or is harmless in combat.
    """
    denied = {"status": "unavailable", "selected_army_id": None,
              "native_preview_required": True, "movement_authorized": False,
              "battle_authorized": False, "ghost_risk_cleared": False}
    threatened_ids = tuple(threatened_army_ids)
    if threatened_ids != (ghost_army_id,):
        return {**denied, "reason": "threatened_scope_not_single_ghost"}
    armies = snapshot.get("player_armies")
    rows = snapshot.get("army_strengths")
    if not isinstance(armies, list) or not isinstance(rows, list):
        return {**denied, "reason": "army_roster_unavailable"}
    controlled = [army for army in armies if isinstance(army, Mapping)
                  and army.get("controllable") is True]
    controlled_ids = {army.get("army_id") for army in controlled}
    if (len(controlled) != 2 or len(controlled_ids) != 2
            or ghost_army_id not in controlled_ids):
        return {**denied, "reason": "bounded_two_army_roster_unavailable"}
    ghost = next((army for army in controlled
                  if army.get("army_id") == ghost_army_id), None)
    if not isinstance(ghost, Mapping) or not _positive_int(ghost.get("current_province_id")):
        return {**denied, "reason": "ghost_position_unavailable"}
    row = next((item for item in rows if isinstance(item, Mapping)
                and item.get("army_id") == ghost_army_id), None)
    if not (isinstance(row, Mapping)
            and row.get("status") == "unavailable"
            and row.get("native_carmy_id") is None
            and row.get("unavailable_reason") == "native_carmy_not_found"):
        return {**denied, "reason": "ghost_carmy_absence_unproven"}
    selected = choose_quiet_movement_preview_subject_v1(
        snapshot, existing_army_id=ghost_army_id,
    )
    if (selected.get("status") != "preview_subject_candidate"
            or selected.get("selected_army_id") == ghost_army_id
            or selected.get("unknown_army_ids") != [ghost_army_id]):
        return {**denied, "reason": "native_subject_unavailable"}
    return {**selected, "status": "threatened_ghost_preview_subject_candidate",
            "ghost_army_id": ghost_army_id,
            "ghost_threat_province_id": ghost["current_province_id"],
            "ghost_risk_cleared": False}


def choose_ongoing_real_route_with_ghost_v1(
    snapshot: Mapping[str, object], *, ghost_army_id: int,
    threatened_army_ids: Iterable[int],
) -> dict[str, object]:
    """Identify an already moving CArmy; leave the ghost in every risk scope."""
    denied = {"status": "unavailable", "selected_army_id": None,
              "movement_authorized": False, "battle_authorized": False,
              "ghost_risk_cleared": False}
    actor = snapshot.get("played_character")
    diagnostics = snapshot.get("diagnostics")
    if not (
        tuple(threatened_army_ids) == (ghost_army_id,)
        and snapshot.get("paused") is True
        and snapshot.get("map_ready") is True
        and isinstance(snapshot.get("snapshot_id"), str)
        and snapshot["snapshot_id"]
        and _positive_int(snapshot.get("revision"))
        and _positive_int(snapshot.get("native_revision"))
        and _positive_int(snapshot.get("date_raw"))
        and isinstance(snapshot.get("episode_run_id"), str)
        and snapshot["episode_run_id"]
        and isinstance(actor, Mapping)
        and _positive_int(actor.get("character_id"))
        and isinstance(diagnostics, Mapping)
        and _positive_int(diagnostics.get("bridge_pid"))
        and _positive_int(diagnostics.get("connection_generation"))
        and snapshot.get("army_strengths_profile") == "ordinary_core_v1"
        and snapshot.get("army_strengths_status") in {"available", "partial"}
        and _positive_int(snapshot.get("army_strengths_query_sequence"))
        and snapshot.get("army_strengths_queried_snapshot_id")
            == snapshot["snapshot_id"]
        and snapshot.get("army_strengths_queried_revision")
            == snapshot["revision"]
    ):
        return {**denied, "reason": "exact_frame_or_threat_scope_unavailable"}
    armies = snapshot.get("player_armies")
    rows = snapshot.get("army_strengths")
    wars = snapshot.get("active_wars")
    if not isinstance(armies, list) or not isinstance(rows, list) or not isinstance(wars, list):
        return {**denied, "reason": "roster_unavailable"}
    controlled = [army for army in armies if isinstance(army, Mapping)
                  and army.get("controllable") is True
                  and army.get("owner_character_id") == actor["character_id"]
                  and _positive_int(army.get("army_id"))]
    if (len(controlled) != 2 or len({army["army_id"] for army in controlled}) != 2
            or ghost_army_id not in {army["army_id"] for army in controlled}):
        return {**denied, "reason": "bounded_two_army_roster_unavailable"}
    ghost = next(army for army in controlled if army["army_id"] == ghost_army_id)
    real = next(army for army in controlled if army["army_id"] != ghost_army_id)
    war_army_ids = {army.get("army_id") for war in wars if isinstance(war, Mapping)
                    for army in (war.get("allied_armies") if isinstance(war.get("allied_armies"), list) else [])
                    if isinstance(army, Mapping)}
    ghost_rows = [row for row in rows if isinstance(row, Mapping)
                  and row.get("army_id") == ghost_army_id]
    real_rows = [row for row in rows if isinstance(row, Mapping)
                 and row.get("army_id") == real["army_id"]]
    if (ghost_army_id not in war_army_ids or real["army_id"] not in war_army_ids
            or len(ghost_rows) != 1 or len(real_rows) != 1):
        return {**denied, "reason": "war_or_strength_scope_unavailable"}
    ghost_row, real_row = ghost_rows[0], real_rows[0]
    route = real.get("route_province_ids")
    if not (
        ghost_row.get("status") == "unavailable"
        and ghost_row.get("scope_role") == "player"
        and ghost_row.get("native_carmy_id") is None
        and ghost_row.get("unavailable_reason") == "native_carmy_not_found"
        and real_row.get("status") == "available"
        and real_row.get("scope_role") == "player"
        and _positive_int(real_row.get("native_carmy_id"))
        and _positive_int(real_row.get("current_soldiers"))
        and _positive_int(ghost.get("current_province_id"))
        and _positive_int(real.get("current_province_id"))
        and ghost.get("move_target_province_id") is None
        and ghost.get("route_province_ids") == []
        and ghost.get("route_read_status") == "complete_empty"
        and _positive_int(real.get("move_target_province_id"))
        and real.get("route_read_status") == "complete_nonempty"
        and isinstance(route, list) and route
        and route[-1] == real["move_target_province_id"]
        and all(army.get("in_combat") is not True
                and army.get("retreating") is not True
                and army.get("army_state") not in {"combat", "retreating"}
                and army.get("army_state_code") not in {2, 6}
                for army in controlled)
    ):
        return {**denied, "reason": "native_route_or_ghost_binding_unavailable"}
    return {
        "status": "ongoing_real_route_candidate",
        "selected_army_id": real["army_id"],
        "ghost_army_id": ghost_army_id,
        "ghost_threat_province_id": ghost["current_province_id"],
        "observed_current_soldiers": real_row["current_soldiers"],
        "source_snapshot_id": snapshot["snapshot_id"],
        "source_revision": snapshot["revision"],
        "source_query_sequence": snapshot["army_strengths_query_sequence"],
        "movement_authorized": False, "battle_authorized": False,
        "ghost_risk_cleared": False,
    }
